module freq_diveven(
    input clk, rst_n,
    output reg clk_div
);
    integer cnt;
    parameter NUM_DIV = 6;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 0;
        else if(cnt==NUM_DIV/2-1) begin
            cnt <= 0;
            clk_div <= ~clk_div;
        end else begin
            cnt <= cnt+1;
        end
    end
endmodule
